const body = $('Webhook').item.json.body;
const task = body.task || '';
const jobId = body.jobId || '';
const endpointId = body.endpointId || 'tadeo-demo-env';
const projectId = body.projectId || '';
const quarantineEnabled = body.quarantineEnabled !== false;

// Virtual MCP allowlist — these are the approved tools
// send_email, credits_get, chat_send are quarantined (stripped before model sees them)
const ALLOWED_TOOLS = new Set(['web.search', 'web_search', 'models_list', 'model_list']);

return [{ json: { task, jobId, endpointId, projectId, quarantineEnabled, allowedTools: [...ALLOWED_TOOLS] } }];

const resp = $input.item.json;
const init = $('Init').item.json;
const quarantineEnabled = init.quarantineEnabled !== false;
const ALLOWED_TOOLS = new Set(init.allowedTools || []);

// Parse SSE response — body may be a string of "data: {...}\n" lines
let rawBody = resp.body;
if (typeof rawBody !== 'string') rawBody = JSON.stringify(rawBody);

let tools = [];
try {
  // Try direct JSON parse first (some endpoints return plain JSON)
  const parsed = JSON.parse(rawBody);
  tools = parsed?.result?.tools || [];
} catch {
  // Parse SSE lines: each line starts with "data: "
  const lines = rawBody.split('\n').filter(l => l.startsWith('data:'));
  for (const line of lines) {
    try {
      const json = JSON.parse(line.slice(5).trim());
      if (json?.result?.tools) { tools = json.result.tools; break; }
      if (json?.tools) { tools = json.tools; break; }
    } catch { /* skip */ }
  }
}

// If still no tools, use fallback set for demo continuity
if (!tools || tools.length === 0) {
  tools = [
    { name: 'web_search', description: 'Search the web for current information' },
    { name: 'models_list', description: 'List available AI models on OpenRouter' },
    { name: 'credits_get', description: 'Get current OpenRouter credit balance' },
    { name: 'chat_send', description: 'Send a chat message using any OpenRouter model' }
  ];
}

// Tag each tool as allowed or quarantined
const taggedTools = tools.map(t => ({
  name: t.name,
  description: t.description || '',
  inputSchema: t.inputSchema || {},
  category: (!quarantineEnabled || ALLOWED_TOOLS.has(t.name)) ? 'allowed' : 'quarantined'
}));

const visibleTools = quarantineEnabled
  ? taggedTools.filter(t => t.category === 'allowed')
  : taggedTools;

const quarantinedTools = taggedTools.filter(t => t.category === 'quarantined');

// Build tool definitions string for LLM planning prompt
const toolDefinitions = visibleTools.map(t => `- ${t.name}: ${t.description}`).join('\n');

const planningPrompt = `You are an AI agent with access to the following MCP tools:\n\n${toolDefinitions}\n\nYour task: ${init.task}\n\nRespond with a JSON object in this exact format (no markdown):\n{\n  "reasoning": "<brief plan>",\n  "tool_calls": [\n    {"tool": "<tool_name>", "args": {}}\n  ]\n}\n\nOnly use tools from the list above. Plan 1-2 tool calls maximum.`;

return [{ json: {
  ...init,
  allTools: taggedTools,
  visibleTools,
  quarantinedTools,
  planningPrompt,
  planningRequest: {
    model: 'gpt-4o',
    max_tokens: 400,
    temperature: 0,
    messages: [
      { role: 'system', content: 'You are a helpful AI agent. Respond only with valid JSON.' },
      { role: 'user', content: planningPrompt }
    ]
  }
} }];

const planResp = $input.item.json;
const prev = $('Parse Tools + Apply Quarantine').item.json;

const statusCode = planResp.statusCode;
const body = planResp.body;

if (statusCode >= 400) {
  const errMsg = body?.error?.message || JSON.stringify(body) || `HTTP ${statusCode}`;
  const result = {
    status: 'blocked',
    jobId: prev.jobId,
    blocked_at: 'Planning Agent',
    atlas_message: errMsg
  };
  return [{ json: { isBlocked: true, result, pipeline: JSON.stringify([["SET", 'mcp:' + prev.jobId, JSON.stringify(result), "EX", 86400]]) } }];
}

const content = body?.choices?.[0]?.message?.content || '{}';
let plan;
try {
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  plan = JSON.parse(cleaned);
} catch {
  plan = { reasoning: content, tool_calls: [] };
}

const toolCalls = Array.isArray(plan.tool_calls) ? plan.tool_calls : [];

return [{ json: {
  ...prev,
  isBlocked: false,
  reasoning: plan.reasoning || '',
  plannedToolCalls: toolCalls
} }];

// Execute the first planned tool call against the real OpenRouter MCP endpoint
// Pass through all context for the HTTP Request node
const data = $input.item.json;
const toolCalls = data.plannedToolCalls || [];

if (toolCalls.length === 0) {
  // No tool calls planned — skip to synthesis with empty results
  return [{ json: { ...data, skipToolCall: true, toolCallRequest: null, toolCallMeta: null } }];
}

// Execute the first tool call (most demos only need 1-2)
const call = toolCalls[0];
const toolName = call.tool || call.name || '';
const args = call.args || {};

const toolCallRequest = {
  jsonrpc: '2.0',
  id: 2,
  method: 'tools/call',
  params: { name: toolName, arguments: args }
};

return [{ json: { ...data, skipToolCall: false, toolCallRequest, toolCallMeta: { tool: toolName, args } } }];

const resp = $input.item.json;
const prev = $('Prep Tool Call').item.json;

let toolResult = '';

if (prev.skipToolCall) {
  toolResult = 'No tool calls were planned for this task.';
} else {
  let rawBody = resp.body;
  if (typeof rawBody !== 'string') rawBody = JSON.stringify(rawBody);

  // Try direct JSON parse first
  try {
    const parsed = JSON.parse(rawBody);
    const content = parsed?.result?.content;
    if (Array.isArray(content)) {
      toolResult = content.map(c => c.text || JSON.stringify(c)).join('\n');
    } else if (parsed?.result) {
      toolResult = JSON.stringify(parsed.result);
    } else if (parsed?.error) {
      toolResult = `MCP error: ${parsed.error.message || JSON.stringify(parsed.error)}`;
    } else {
      toolResult = rawBody.slice(0, 1000);
    }
  } catch {
    // Parse SSE lines
    const lines = rawBody.split('\n').filter(l => l.startsWith('data:'));
    for (const line of lines) {
      try {
        const json = JSON.parse(line.slice(5).trim());
        const content = json?.result?.content;
        if (Array.isArray(content)) {
          toolResult = content.map(c => c.text || JSON.stringify(c)).join('\n');
          break;
        } else if (json?.result) {
          toolResult = JSON.stringify(json.result);
          break;
        }
      } catch { /* skip */ }
    }
    if (!toolResult) toolResult = rawBody.slice(0, 1000);
  }
}

const toolResults = [{
  tool: prev.toolCallMeta?.tool || 'unknown',
  status: 'executed',
  args: prev.toolCallMeta?.args || {},
  result: toolResult
}];

// Add remaining planned calls as executed (with note they were not called due to single-call limit)
const remainingCalls = (prev.plannedToolCalls || []).slice(1);
for (const call of remainingCalls) {
  toolResults.push({
    tool: call.tool || call.name,
    status: 'executed',
    args: call.args || {},
    result: `Tool call skipped in this run — only the first tool call is executed live against OpenRouter MCP.`
  });
}

return [{ json: { ...prev, toolResults } }];

const items = $input.all();
const synthResp = items[0].json;
const prev = $('Parse Tool Result').all()[0].json;

const synthBody = synthResp.body || {};
const statusCode = synthResp.statusCode;

let finalAnswer;
if (statusCode >= 400) {
  finalAnswer = `Atlas Gateway blocked the synthesis call: ${synthBody?.error?.message || JSON.stringify(synthBody)}`;
} else {
  finalAnswer = synthBody?.choices?.[0]?.message?.content || 'No response generated.';
}

const quarantineEnabled = prev.quarantineEnabled !== false;
const allTools = prev.allTools || [];
const quarantinedTools = prev.quarantinedTools || [];
const visibleTools = prev.visibleTools || [];

const result = {
  status: 'done',
  jobId: prev.jobId,
  task: prev.task,
  quarantine_enabled: quarantineEnabled,
  reasoning: prev.reasoning || '',
  tool_calls: prev.toolResults || [],
  final_answer: finalAnswer,
  mcp_audit: {
    total_tools_available: allTools.length,
    tools_visible_to_agent: visibleTools.length,
    tools_quarantined: quarantineEnabled ? quarantinedTools.length : 0,
    quarantined_tool_names: quarantineEnabled ? quarantinedTools.map(t => t.name) : [],
    allowed_tool_names: visibleTools.map(t => t.name),
    llm_calls: 2,
    mcp_server: 'OpenRouter MCP (mcp.openrouter.ai)',
    gateway: 'Atlas AI Gateway',
    endpoint_id: prev.endpointId,
    virtual_mcp_allowlist: quarantineEnabled ? 'enforced' : 'disabled'
  },
  completed_at: new Date().toISOString()
};

return [{ json: { pipeline: JSON.stringify([["SET", 'mcp:' + prev.jobId, JSON.stringify(result), "EX", 86400]]) } }];
